// AuthServiceHandler is an implementation of the mistgate.admin.v1.AuthService service.
type AuthServiceHandler interface {
	// Public. What the sign-in and setup pages need before anyone is signed in.
	GetLoginInfo(context.Context, *connect.Request[v1.GetLoginInfoRequest]) (*connect.Response[v1.GetLoginInfoResponse], error)
	// Public. First admin. `mistgate setup` prints a one-time link carrying setup_token (valid 30 min).
	// method PASSKEY (default) continues with FinishSetup.credential_json; method PASSWORD hashes the
	// password, returns a TOTP secret to scan and continues with FinishSetup.totp_code.
	BeginSetup(context.Context, *connect.Request[v1.BeginSetupRequest]) (*connect.Response[v1.BeginSetupResponse], error)
	FinishSetup(context.Context, *connect.Request[v1.FinishSetupRequest]) (*connect.Response[v1.FinishSetupResponse], error)
	// Public. Passkey sign-in with discoverable credentials (no username field).
	BeginLogin(context.Context, *connect.Request[v1.BeginLoginRequest]) (*connect.Response[v1.BeginLoginResponse], error)
	FinishLogin(context.Context, *connect.Request[v1.FinishLoginRequest]) (*connect.Response[v1.FinishLoginResponse], error)
	// Public. Sign-in with login + password + 6-digit authenticator code. Failures are
	// UNAUTHENTICATED with a SignInFailure detail; after 5 failures the login is locked
	// (locked_until_unix > 0) even for the right credentials.
	PasswordLogin(context.Context, *connect.Request[v1.PasswordLoginRequest]) (*connect.Response[v1.PasswordLoginResponse], error)
	// Public; tolerates a missing or expired session.
	Logout(context.Context, *connect.Request[v1.LogoutRequest]) (*connect.Response[v1.LogoutResponse], error)
	// The signed-in admin. Returns Unauthenticated without a valid session.
	Me(context.Context, *connect.Request[v1.MeRequest]) (*connect.Response[v1.MeResponse], error)
	// Settings -> Security. The signed-in admin's own passkeys.
	ListPasskeys(context.Context, *connect.Request[v1.ListPasskeysRequest]) (*connect.Response[v1.ListPasskeysResponse], error)
	BeginAddPasskey(context.Context, *connect.Request[v1.BeginAddPasskeyRequest]) (*connect.Response[v1.BeginAddPasskeyResponse], error)
	FinishAddPasskey(context.Context, *connect.Request[v1.FinishAddPasskeyRequest]) (*connect.Response[v1.FinishAddPasskeyResponse], error)
	// FAILED_PRECONDITION if it is the only way the admin can sign in.
	RemovePasskey(context.Context, *connect.Request[v1.RemovePasskeyRequest]) (*connect.Response[v1.RemovePasskeyResponse], error)
	// Settings -> Security -> "Password and code": the signed-in admin's own password + authenticator-code sign-in, the
	// fallback to passkeys. GetPasswordLogin says whether the admin has one. A lost phone with no session left is
	// `mistgate auth reset-login <login>` on the panel server (the CLI), not an RPC.
	GetPasswordLogin(context.Context, *connect.Request[v1.GetPasswordLoginRequest]) (*connect.Response[v1.GetPasswordLoginResponse], error)
	// A new password. Needs a step-up and the current password, and ends the admin's other sessions. Errors:
	// FAILED_PRECONDITION "no_password_login"; INVALID_ARGUMENT "wrong_password" (it counts against the step-up lock: five
	// wrong proofs lock it for 15 minutes, then RESOURCE_EXHAUSTED) or the password rule.
	ChangePassword(context.Context, *connect.Request[v1.ChangePasswordRequest]) (*connect.Response[v1.ChangePasswordResponse], error)
	// A new authenticator secret, shown as a QR code like in the setup wizard and confirmed by its first code. Needs a
	// step-up. With a password login it replaces the app ("re-bind": login and password stay, the other sessions end);
	// without one it adds the password login, and then login and password are required. Errors: FAILED_PRECONDITION
	// "no_master_key"; INVALID_ARGUMENT "password_login_exists" (a login or password sent for a re-bind) or the login and
	// password rules; ALREADY_EXISTS "login_taken". FinishTotpEnrollment takes a code of the NEW secret: INVALID_ARGUMENT
	// "invalid_code" may be retried on the same ceremony (5 tries), "enrollment_expired" means start again.
	BeginTotpEnrollment(context.Context, *connect.Request[v1.BeginTotpEnrollmentRequest]) (*connect.Response[v1.BeginTotpEnrollmentResponse], error)
	FinishTotpEnrollment(context.Context, *connect.Request[v1.FinishTotpEnrollmentRequest]) (*connect.Response[v1.FinishTotpEnrollmentResponse], error)
	// Settings -> Sessions. The signed-in admin's own sessions.
	ListSessions(context.Context, *connect.Request[v1.ListSessionsRequest]) (*connect.Response[v1.ListSessionsResponse], error)
	EndSession(context.Context, *connect.Request[v1.EndSessionRequest]) (*connect.Response[v1.EndSessionResponse], error)
	EndOtherSessions(context.Context, *connect.Request[v1.EndOtherSessionsRequest]) (*connect.Response[v1.EndOtherSessionsResponse], error)
	// Settings -> Audit. Owner only.
	ListAudit(context.Context, *connect.Request[v1.ListAuditRequest]) (*connect.Response[v1.ListAuditResponse], error)
	// Settings -> Security -> Captcha. Owner only. The secret key is never returned.
	GetSecuritySettings(context.Context, *connect.Request[v1.GetSecuritySettingsRequest]) (*connect.Response[v1.GetSecuritySettingsResponse], error)
	UpdateSecuritySettings(context.Context, *connect.Request[v1.UpdateSecuritySettingsRequest]) (*connect.Response[v1.UpdateSecuritySettingsResponse], error)
	// Step-up re-authentication. Adding or removing a passkey, ending another session, changing the password and binding
	// an authenticator app need the admin to have proved a sign-in factor within the last 5 minutes (signing in counts): otherwise
	// the call is PERMISSION_DENIED with a StepUpRequired detail and the UI asks for a passkey or an
	// authenticator code, then retries. BeginStepUp + FinishStepUp with a passkey; FinishStepUp with
	// only totp_code for a password admin (no BeginStepUp needed). Me and FinishStepUp report
	// step_up_until_unix so the UI knows when to ask.
	BeginStepUp(context.Context, *connect.Request[v1.BeginStepUpRequest]) (*connect.Response[v1.BeginStepUpResponse], error)
	FinishStepUp(context.Context, *connect.Request[v1.FinishStepUpRequest]) (*connect.Response[v1.FinishStepUpResponse], error)
}

